  ('/','home.text.h1.body','Home / Text after Handmade mixed media jewelry, art, gifts & vintage find','text','[data-content-slot="home.text.h1.body"]','textContent','Workshop-made creations from Southern Ontario: polymer clay, metalwork, engraving, resin, 3D design, sublimation, collectibles, and one-of-a-kind experiments.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/','home.text.heading.2','Home / Heading: What we make, find, and experiment with','text','[data-content-slot="home.text.heading.2"]','textContent','What we make, find, and experiment with',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/','home.text.heading.2.body','Home / Text after What we make, find, and experiment with','text','[data-content-slot="home.text.heading.2.body"]','textContent','Choose a path by material, making method, gift idea, or collected find. These visual cards are category signposts; actual product availability stays visible on each listing.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
