  ('/','home.text.heading.8.body','Home / Text after Collections','text','[data-content-slot="home.text.heading.8.body"]','textContent','Browse handmade, vintage, collectible, antique, oddity, and pre-built paths more clearly.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.hero.image','About / Hero image','image','[data-media-slot="about.hero.image"]','src','/assets/images/site/about-real-workshop.webp','Devil n Dove maker and workshop story',1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.image.1','About / Devil n Dove maker and workshop story','image','[data-media-slot="about.image.1"]','src','/assets/images/site/about-real-workshop.webp','Devil n Dove maker and workshop story',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.image.2','About / Workshop and product collage','image','[data-media-slot="about.image.2"]','src','/assets/mainpage-collage.webp','Workshop and product collage',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.image.3','About / Devil n Dove mark','image','[data-media-slot="about.image.3"]','src','/assets/mark.png','Devil n Dove mark',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.section.visual.1','About / What we do visual','image','[data-media-slot="about.section.visual.1"]','src','/assets/placeholders/media-content/about-section-visual-1.svg','Placeholder for What we do',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.h1','About / Main heading: About Devil n Dove','text','[data-content-slot="about.text.h1"]','textContent','About Devil n Dove',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.h1.body','About / Text after About Devil n Dove','text','[data-content-slot="about.text.h1.body"]','textContent','Devil n Dove is our workshop, our creative outlet, and our way of keeping life moving—especially on the days that don’t cooperate. We’re not chasing perfection. We’re chasing progress, curiosity, and the kind of making that feels like breathing again.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.2','About / Heading: What we do','text','[data-content-slot="about.text.heading.2"]','textContent','What we do',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.3','About / Heading: Why we do it','text','[data-content-slot="about.text.heading.3"]','textContent','Why we do it',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.3.body','About / Text after Why we do it','text','[data-content-slot="about.text.heading.3.body"]','textContent','Making is therapy here. It’s structure, focus, and a reason to show up. We work around real limitations—and we share that honestly—because it’s part of the story and part of the strength.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.4','About / Heading: What you’ll find on this site','text','[data-content-slot="about.text.heading.4"]','textContent','What you’ll find on this site',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.5','About / Heading: Sourcing, provenance, and condition','text','[data-content-slot="about.text.heading.5"]','textContent','Sourcing, provenance, and condition',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.5.body','About / Text after Sourcing, provenance, and condition','text','[data-content-slot="about.text.heading.5.body"]','textContent','Devil n Dove is not only handmade work. We also sell vintage pieces, oddities, old tools, collectibles, and pre-built items. When something is not workshop-made, we want that stated plainly with sourcing notes, condition summaries, era clues, and outside-listing links where needed.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.6','About / Heading: How sales channels work','text','[data-content-slot="about.text.heading.6"]','textContent','How sales channels work',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.6.body','About / Text after How sales channels work','text','[data-content-slot="about.text.heading.6.body"]','textContent','Some items are sold directly on Devil n Dove, some are listed both here and elsewhere, and some are external-only listings. We keep that visible so buyers understand whether they are purchasing a workshop-made piece, reserving a collectible, or following a link out to another marketplace.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.7','About / Heading: Snapshots from the bench','text','[data-content-slot="about.text.heading.7"]','textContent','Snapshots from the bench',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.7.body','About / Text after Snapshots from the bench','text','[data-content-slot="about.text.heading.7.body"]','textContent','The real stuff: tools, in-progress chaos, and the pieces that make it out the other side.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.8','About / Heading: Our mark','text','[data-content-slot="about.text.heading.8"]','textContent','Our mark',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/about','about.text.heading.8.body','About / Text after Our mark','text','[data-content-slot="about.text.heading.8.body"]','textContent','If the full logo is our shout, this is our whisper.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
