  ('/gallery','gallery.text.h1.body','Gallery / Text after Art, jewelry and workshop experiments','text','[data-content-slot="gallery.text.h1.body"]','textContent','A living portfolio of what we’ve made — jewelry, mixed media, prototypes, and the occasional happy accident.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
