  ('/creations','creations.text.h1','Showcase / Creations / Main heading: Browse Devil n Dove creations','text','[data-content-slot="creations.text.h1"]','textContent','Browse Devil n Dove creations',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/creations','creations.text.h1.body','Showcase / Creations / Text after Browse Devil n Dove creations','text','[data-content-slot="creations.text.h1.body"]','textContent','This page is built to scale. Right now it shows the finished pieces already in your JSON, and later it can grow into the main home for hundreds of rings, pendants, sets, experiments, and one-off builds.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
