  ('/workshop-journal','workshop-journal.text.h1','Workshop / Workroom Journal / Main heading: Workshop notes, care guides, and honest maker stories','text','[data-content-slot="workshop-journal.text.h1"]','textContent','Workshop notes, care guides, and honest maker stories',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.h1.body','Workshop / Workroom Journal / Text after Workshop notes, care guides, and honest maker stories','text','[data-content-slot="workshop-journal.text.h1.body"]','textContent','Short practical notes from a Southern Ontario workshop: what we make, how we care for it, how we describe vintage and sourced items, and what we learn while experimenting.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.2','Workshop / Workroom Journal / Heading: Why this journal exists','text','[data-content-slot="workshop-journal.text.heading.2"]','textContent','Why this journal exists',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.2.body','Workshop / Workroom Journal / Text after Why this journal exists','text','[data-content-slot="workshop-journal.text.heading.2.body"]','textContent','Handmade pieces and found objects are easier to choose when their materials, process, condition, care, and limits are explained plainly. We will add real project stories only when they are accurate, approved, and useful to a buyer or fellow maker.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.3','Workshop / Workroom Journal / Heading: Polymer clay earring care','text','[data-content-slot="workshop-journal.text.heading.3"]','textContent','Polymer clay earring care',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.3.body','Workshop / Workroom Journal / Text after Polymer clay earring care','text','[data-content-slot="workshop-journal.text.heading.3.body"]','textContent','A plain-language care guide for polymer clay jewelry, storage, cleaning, and keeping expectations realistic.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.4','Workshop / Workroom Journal / Heading: Coin and spoon ring care','text','[data-content-slot="workshop-journal.text.heading.4"]','textContent','Coin and spoon ring care',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.4.body','Workshop / Workroom Journal / Text after Coin and spoon ring care','text','[data-content-slot="workshop-journal.text.heading.4.body"]','textContent','What to check before wearing, cleaning, storing, gifting, or requesting a size adjustment for repurposed metal rings.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.5','Workshop / Workroom Journal / Heading: Handmade, vintage, and sourced','text','[data-content-slot="workshop-journal.text.heading.5"]','textContent','Handmade, vintage, and sourced',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.5.body','Workshop / Workroom Journal / Text after Handmade, vintage, and sourced','text','[data-content-slot="workshop-journal.text.heading.5.body"]','textContent','How we describe the difference between something we made, a found item, a collectible, and a vintage piece.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.6','Workshop / Workroom Journal / Heading: Workshop experiments','text','[data-content-slot="workshop-journal.text.heading.6"]','textContent','Workshop experiments',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.6.body','Workshop / Workroom Journal / Text after Workshop experiments','text','[data-content-slot="workshop-journal.text.heading.6.body"]','textContent','Future process posts will show materials, tools, tests, lessons, and the occasional honest failure—without pretending every experiment is perfect.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.7','Workshop / Workroom Journal / Heading: Gift guides','text','[data-content-slot="workshop-journal.text.heading.7"]','textContent','Gift guides',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.7.body','Workshop / Workroom Journal / Text after Gift guides','text','[data-content-slot="workshop-journal.text.heading.7.body"]','textContent','Ideas for giftable, one-of-a-kind, local-pickup, maker, gamer, fantasy, and small-budget finds as real inventory becomes available.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.8','Workshop / Workroom Journal / Heading: Local handmade notes','text','[data-content-slot="workshop-journal.text.heading.8"]','textContent','Local handmade notes',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal','workshop-journal.text.heading.8.body','Workshop / Workroom Journal / Text after Local handmade notes','text','[data-content-slot="workshop-journal.text.heading.8.body"]','textContent','Pickup, market, workshop, and Southern Ontario context should stay accurate and helpful—not exaggerated for search engines.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
