  ('/collections','collections.text.h1','Collections / Main heading: Browse Devil n Dove collections in a clearer way','text','[data-content-slot="collections.text.h1"]','textContent','Browse Devil n Dove collections in a clearer way',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.h1.body','Collections / Text after Browse Devil n Dove collections in a clearer way','text','[data-content-slot="collections.text.h1.body"]','textContent','Use these collection paths when you want to separate workshop-made pieces from vintage, collectible, antique, oddity, and pre-built items. This keeps origin, condition, and sale channel clearer before you open a product.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.2','Collections / Heading: Collection overview photo','text','[data-content-slot="collections.text.heading.2"]','textContent','Collection overview photo',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.2.body','Collections / Text after Collection overview photo','text','[data-content-slot="collections.text.heading.2.body"]','textContent','Representative collection overview photo helps buyers choose between jewelry, gifts, candles, soap, engraving, and vintage finds.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.3','Collections / Heading: Why this page exists','text','[data-content-slot="collections.text.heading.3"]','textContent','Why this page exists',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.4','Collections / Heading: Handmade creations','text','[data-content-slot="collections.text.heading.4"]','textContent','Handmade creations',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.4.body','Collections / Text after Handmade creations','text','[data-content-slot="collections.text.heading.4.body"]','textContent','Finished jewelry, experiments, resin, clay, mixed media, and workshop-made pieces that belong to the Devil n Dove making story.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.5','Collections / Heading: Vintage & antique finds','text','[data-content-slot="collections.text.heading.5"]','textContent','Vintage & antique finds',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.5.body','Collections / Text after Vintage & antique finds','text','[data-content-slot="collections.text.heading.5.body"]','textContent','Older pieces, rescued objects, and era-tagged stock where age, patina, testing, and condition need to stay visible.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.6','Collections / Heading: Collectibles & oddities','text','[data-content-slot="collections.text.heading.6"]','textContent','Collectibles & oddities',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.6.body','Collections / Text after Collectibles & oddities','text','[data-content-slot="collections.text.heading.6.body"]','textContent','Curiosities, unusual finds, pre-built stock, old tools, and collectible pieces that are not represented as newly handmade work.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.7','Collections / Heading: Shop by sale channel','text','[data-content-slot="collections.text.heading.7"]','textContent','Shop by sale channel',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.7.body','Collections / Text after Shop by sale channel','text','[data-content-slot="collections.text.heading.7.body"]','textContent','Some items stay fully on Devil n Dove, some are hybrid-listed, and some are external-only. Keep that channel visible before you commit to a buying path.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.8','Collections / Heading: Condition, provenance, and support','text','[data-content-slot="collections.text.heading.8"]','textContent','Condition, provenance, and support',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/collections','collections.text.heading.8.body','Collections / Text after Condition, provenance, and support','text','[data-content-slot="collections.text.heading.8.body"]','textContent','When a piece is vintage, collectible, or found, the listing should make space for wear, repairs, unknowns, testing notes, provenance clues, and pickup or availability questions.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
