  ('/events','events.text.h1','Events & Markets / Main heading: See how Devil n Dove handles recurring events, markets, and pop-ups','text','[data-content-slot="events.text.h1"]','textContent','See how Devil n Dove handles recurring events, markets, and pop-ups',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/events','events.text.h1.body','Events & Markets / Text after See how Devil n Dove handles recurring events, markets,','text','[data-content-slot="events.text.h1.body"]','textContent','Some pieces make the most sense online, some work better through pickup-friendly conversations, and some belong at a local market table where condition, scale, and provenance can be discussed in person.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/events','events.text.heading.2','Events & Markets / Heading: Events display photo','text','[data-content-slot="events.text.heading.2"]','textContent','Events display photo',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/events','events.text.heading.2.body','Events & Markets / Text after Events display photo','text','[data-content-slot="events.text.heading.2.body"]','textContent','Use approved market, pickup, or workshop proof once available.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
