  ('/events','events.text.heading.4','Events & Markets / Heading: What we can bring to events','text','[data-content-slot="events.text.heading.4"]','textContent','What we can bring to events',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/events','events.text.heading.4.body','Events & Markets / Text after What we can bring to events','text','[data-content-slot="events.text.heading.4.body"]','textContent','Handmade jewelry, creative experiments, workshop-made pieces, and selected found/vintage stock can all fit the event side of Devil n Dove, but not every item belongs in every venue.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/events','events.text.heading.5','Events & Markets / Heading: Current event status','text','[data-content-slot="events.text.heading.5"]','textContent','Current event status',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/events','events.text.heading.5.body','Events & Markets / Text after Current event status','text','[data-content-slot="events.text.heading.5.body"]','textContent','This page now supports recurring market dates, pop-up notes, vendor-interest calls, and event images through the community-content API. If nothing is published yet, use Contact to ask whether a piece is available for pickup, viewing, or local handoff.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
