  ('/socials','socials.text.h1.body','Social Hub / Text after Devil n Dove social hub','text','[data-content-slot="socials.text.h1.body"]','textContent','Use one page to point visitors toward your latest videos and social profiles. This pass keeps public profile links, derived YouTube thumbnail fallbacks, and a safer video snapshot when the live feed has trouble.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
