  ('/custom-candle-making-ontario','custom-candle-making-ontario.text.h1','Custom Candle Making / Main heading: Custom candle making in Southern Ontario','text','[data-content-slot="custom-candle-making-ontario.text.h1"]','textContent','Custom candle making in Southern Ontario',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/custom-candle-making-ontario','custom-candle-making-ontario.text.h1.body','Custom Candle Making / Text after Custom candle making in Southern Ontario','text','[data-content-slot="custom-candle-making-ontario.text.h1.body"]','textContent','Request small-batch candle ideas for gifts, memorials, markets, holidays, room themes, or matching handmade sets. We review each request before quoting materials, timing, scent direction, labels, and pickup or shipping.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/custom-candle-making-ontario','custom-candle-making-ontario.text.heading.2','Custom Candle Making / Heading: Gift candles','text','[data-content-slot="custom-candle-making-ontario.text.heading.2"]','textContent','Gift candles',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/custom-candle-making-ontario','custom-candle-making-ontario.text.heading.2.body','Custom Candle Making / Text after Gift candles','text','[data-content-slot="custom-candle-making-ontario.text.heading.2.body"]','textContent','Personalized label wording, colours, packaging notes, and gift timing can be reviewed before we turn the idea into a quote.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/custom-candle-making-ontario','custom-candle-making-ontario.text.heading.3','Custom Candle Making / Heading: Small batches','text','[data-content-slot="custom-candle-making-ontario.text.heading.3"]','textContent','Small batches',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/custom-candle-making-ontario','custom-candle-making-ontario.text.heading.3.body','Custom Candle Making / Text after Small batches','text','[data-content-slot="custom-candle-making-ontario.text.heading.3.body"]','textContent','We can plan small handmade batches instead of mass production, which fits the Devil n Dove workshop pace and helps avoid overpromising.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/custom-candle-making-ontario','custom-candle-making-ontario.text.heading.4','Custom Candle Making / Heading: Consent-aware photos','text','[data-content-slot="custom-candle-making-ontario.text.heading.4"]','textContent','Consent-aware photos',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
