  ('/workshop-journal/story','workshop-journal-story.hero.image','Workshop Journal Story / Hero image','image','[data-media-slot="workshop-journal-story.hero.image"]','src','/assets/placeholders/media-content/workshop-journal-story-hero-image.svg','Workshop Journal Story visual',1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/story','workshop-journal-story.background.hero','Workshop Journal Story / Hero background','background','[data-media-background-slot="workshop-journal-story.background.hero"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/story','workshop-journal-story.text.h1','Workshop Journal Story / Main heading: Workshop Journal story','text','[data-content-slot="workshop-journal-story.text.h1"]','textContent','Workshop Journal story',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/story','workshop-journal-story.text.h1.body','Workshop Journal Story / Text after Workshop Journal story','text','[data-content-slot="workshop-journal-story.text.h1.body"]','textContent','Loading a reviewed finished-project story…',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.hero.image','Coin & Spoon Ring Care / Hero image','image','[data-media-slot="workshop-journal-coin-and-spoon-ring-care.hero.image"]','src','/assets/placeholders/media-content/workshop-journal-coin-and-spoon-ring-care-hero-image.svg','Coin & Spoon Ring Care visual',1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.section.visual.1','Coin & Spoon Ring Care / Before wearing visual','image','[data-media-slot="workshop-journal-coin-and-spoon-ring-care.section.visual.1"]','src','/assets/placeholders/media-content/workshop-journal-coin-and-spoon-ring-care-section-visual-1.svg','Placeholder for Before wearing',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.background.hero','Coin & Spoon Ring Care / Hero background','background','[data-media-background-slot="workshop-journal-coin-and-spoon-ring-care.background.hero"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.background.section-1','Coin & Spoon Ring Care / Before wearing background','background','[data-media-background-slot="workshop-journal-coin-and-spoon-ring-care.background.section-1"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.background.section-2','Coin & Spoon Ring Care / Fit and adjustment background','background','[data-media-background-slot="workshop-journal-coin-and-spoon-ring-care.background.section-2"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.h1','Coin & Spoon Ring Care / Main heading: Coin and spoon ring care','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.h1"]','textContent','Coin and spoon ring care',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.h1.body','Coin & Spoon Ring Care / Text after Coin and spoon ring care','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.h1.body"]','textContent','Repurposed-metal rings can carry texture, pattern, age, and character that mass-produced jewelry does not. Their care should match the actual metal, finish, sizing, and condition of the piece.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.heading.2','Coin & Spoon Ring Care / Heading: Before wearing','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.heading.2"]','textContent','Before wearing',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.heading.2.body','Coin & Spoon Ring Care / Text after Before wearing','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.heading.2.body"]','textContent','Check the listing for material and size. Do not assume every patterned ring is sterling silver: some pieces are stainless steel, plated, mixed-metal, or of unknown composition. If you have a metal sensitivity, ask before purchase.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.heading.3','Coin & Spoon Ring Care / Heading: Fit and adjustment','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.heading.3"]','textContent','Fit and adjustment',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.heading.3.body','Coin & Spoon Ring Care / Text after Fit and adjustment','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.heading.3.body"]','textContent','Rings should not be forced over a knuckle or squeezed repeatedly. Repeated bending can stress some designs, patterns, solder points, or older metal. Contact us before using a ring stretcher, reducer, or pliers on a handmade or repurposed ring.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.heading.4','Coin & Spoon Ring Care / Heading: Cleaning and storage','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.heading.4"]','textContent','Cleaning and storage',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.heading.4.body','Coin & Spoon Ring Care / Text after Cleaning and storage','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.heading.4.body"]','textContent','Use a soft dry cloth first. Store rings separately from abrasive tools and loose hardware. If a piece has a special patina, darkened detail, stone, resin, or plated finish, ask before using a polish or chemical cleaner.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.heading.5','Coin & Spoon Ring Care / Heading: Gift note','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.heading.5"]','textContent','Gift note',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.heading.5.body','Coin & Spoon Ring Care / Text after Gift note','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.heading.5.body"]','textContent','A ring size, material note, and care card make a gift easier to enjoy. For custom or themed ring work, confirm sizing and timing before payment or engraving begins.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.heading.6','Coin & Spoon Ring Care / Heading: When in doubt, ask first','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.heading.6"]','textContent','When in doubt, ask first',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/coin-and-spoon-ring-care','workshop-journal-coin-and-spoon-ring-care.text.heading.6.body','Coin & Spoon Ring Care / Text after When in doubt, ask first','text','[data-content-slot="workshop-journal-coin-and-spoon-ring-care.text.heading.6.body"]','textContent','If a listing has a special finish, a vintage condition detail, a custom sizing question, or product-specific safety notes, the individual listing and direct message take priority over this general guide.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.hero.image','Polymer Clay Earring Care / Hero image','image','[data-media-slot="workshop-journal-polymer-clay-earring-care.hero.image"]','src','/assets/placeholders/media-content/workshop-journal-polymer-clay-earring-care-hero-image.svg','Polymer Clay Earring Care visual',1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.section.visual.1','Polymer Clay Earring Care / Wear and storage visual','image','[data-media-slot="workshop-journal-polymer-clay-earring-care.section.visual.1"]','src','/assets/placeholders/media-content/workshop-journal-polymer-clay-earring-care-section-visual-1.svg','Placeholder for Wear and storage',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.background.hero','Polymer Clay Earring Care / Hero background','background','[data-media-background-slot="workshop-journal-polymer-clay-earring-care.background.hero"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.background.section-1','Polymer Clay Earring Care / Wear and storage background','background','[data-media-background-slot="workshop-journal-polymer-clay-earring-care.background.section-1"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.background.section-2','Polymer Clay Earring Care / Cleaning background','background','[data-media-background-slot="workshop-journal-polymer-clay-earring-care.background.section-2"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.h1','Polymer Clay Earring Care / Main heading: Polymer clay earring care','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.h1"]','textContent','Polymer clay earring care',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.h1.body','Polymer Clay Earring Care / Text after Polymer clay earring care','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.h1.body"]','textContent','Polymer clay earrings are lightweight and practical for everyday wear, but like other handmade jewelry they benefit from gentle handling and sensible storage.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.heading.2','Polymer Clay Earring Care / Heading: Wear and storage','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.heading.2"]','textContent','Wear and storage',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.heading.2.body','Polymer Clay Earring Care / Text after Wear and storage','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.heading.2.body"]','textContent','Put earrings on after hair spray, perfume, lotions, and makeup have had time to settle. Store pairs where they are not pressed under heavy metal pieces, sharp edges, or loose tools that can scratch the surface.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.heading.3','Polymer Clay Earring Care / Heading: Cleaning','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.heading.3"]','textContent','Cleaning',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.heading.3.body','Polymer Clay Earring Care / Text after Cleaning','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.heading.3.body"]','textContent','Start with a soft dry cloth. If the listing permits it, a barely damp soft cloth may be used for a small surface mark, then dry the piece right away. Do not soak handmade earrings or use harsh household cleaners unless the product-specific care note says it is safe.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.heading.4','Polymer Clay Earring Care / Heading: Handmade variation','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.heading.4"]','textContent','Handmade variation',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.heading.4.body','Polymer Clay Earring Care / Text after Handmade variation','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.heading.4.body"]','textContent','Small differences in pattern, marbling, texture, placement, or finish are normal in handmade work. We describe obvious variation and use close-up photos where possible so the piece a buyer receives is clear.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.heading.5','Polymer Clay Earring Care / Heading: When to contact us','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.heading.5"]','textContent','When to contact us',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.heading.5.body','Polymer Clay Earring Care / Text after When to contact us','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.heading.5.body"]','textContent','Contact us before trying a repair, glue, solvent, polish, or strong cleaner. A metal finding, resin accent, paint, or sealant can change the right care method for one specific piece.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.heading.6','Polymer Clay Earring Care / Heading: When in doubt, ask first','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.heading.6"]','textContent','When in doubt, ask first',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/polymer-clay-earring-care','workshop-journal-polymer-clay-earring-care.text.heading.6.body','Polymer Clay Earring Care / Text after When in doubt, ask first','text','[data-content-slot="workshop-journal-polymer-clay-earring-care.text.heading.6.body"]','textContent','If a listing has a special finish, a vintage condition detail, a custom sizing question, or product-specific safety notes, the individual listing and direct message take priority over this general guide.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.hero.image','Handmade / Vintage / Sourced Guide / Hero image','image','[data-media-slot="workshop-journal-handmade-vintage-sourced-guide.hero.image"]','src','/assets/placeholders/media-content/workshop-journal-handmade-vintage-sourced-guide-hero-image.svg','Handmade / Vintage / Sourced Guide visual',1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.section.visual.1','Handmade / Vintage / Sourced Guide / Handmade visual','image','[data-media-slot="workshop-journal-handmade-vintage-sourced-guide.section.visual.1"]','src','/assets/placeholders/media-content/workshop-journal-handmade-vintage-sourced-guide-section-visual-1.svg','Placeholder for Handmade',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.background.hero','Handmade / Vintage / Sourced Guide / Hero background','background','[data-media-background-slot="workshop-journal-handmade-vintage-sourced-guide.background.hero"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.background.section-1','Handmade / Vintage / Sourced Guide / Handmade background','background','[data-media-background-slot="workshop-journal-handmade-vintage-sourced-guide.background.section-1"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.background.section-2','Handmade / Vintage / Sourced Guide / Vintage, antique, collectible, and sourced background','background','[data-media-background-slot="workshop-journal-handmade-vintage-sourced-guide.background.section-2"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.h1','Handmade / Vintage / Sourced Guide / Main heading: Handmade, vintage, and sourced: what the labels mean','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.h1"]','textContent','Handmade, vintage, and sourced: what the labels mean',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.h1.body','Handmade / Vintage / Sourced Guide / Text after Handmade, vintage, and sourced: what the labels mean','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.h1.body"]','textContent','Clear labels help buyers understand what they are looking at before they decide whether a piece is right for them.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.heading.2','Handmade / Vintage / Sourced Guide / Heading: Handmade','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.heading.2"]','textContent','Handmade',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.heading.2.body','Handmade / Vintage / Sourced Guide / Text after Handmade','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.heading.2.body"]','textContent','Handmade means the item was made, assembled, carved, cast, engraved, printed, painted, polished, or otherwise worked on in the Devil n Dove workshop. Each listing should state actual materials, process notes, and any meaningful handmade variation.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.heading.3','Handmade / Vintage / Sourced Guide / Heading: Vintage, antique, collectible, and sourced','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.heading.3"]','textContent','Vintage, antique, collectible, and sourced',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
INSERT INTO media_content_slots(page_path,slot_key,slot_label,slot_type,target_selector,target_attribute,source_snapshot,source_alt_snapshot,is_required,is_active,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.heading.3.body','Handmade / Vintage / Sourced Guide / Text after Vintage, antique, collectible, and sourced','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.heading.3.body"]','textContent','These labels describe found or pre-existing items. We do not represent them as newly handmade. Listings should make room for condition, wear, repairs, known or estimated era, provenance clues, cleaning notes, and unknowns.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.heading.4','Handmade / Vintage / Sourced Guide / Heading: One of a kind and small batch','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.heading.4"]','textContent','One of a kind and small batch',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.heading.4.body','Handmade / Vintage / Sourced Guide / Text after One of a kind and small batch','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.heading.4.body"]','textContent','One of a kind means that exact item is not expected to be duplicated. Small batch means related pieces may exist, but colour, pattern, placement, or finish can vary. The product page should say which situation applies.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.heading.5','Handmade / Vintage / Sourced Guide / Heading: Questions before purchase','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.heading.5"]','textContent','Questions before purchase',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.heading.5.body','Handmade / Vintage / Sourced Guide / Text after Questions before purchase','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.heading.5.body"]','textContent','Ask about condition, material, size, pickup, shipping, or a close-up before buying. Clear questions are part of a good handmade and vintage shopping experience.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.heading.6','Handmade / Vintage / Sourced Guide / Heading: When in doubt, ask first','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.heading.6"]','textContent','When in doubt, ask first',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/workshop-journal/handmade-vintage-sourced-guide','workshop-journal-handmade-vintage-sourced-guide.text.heading.6.body','Handmade / Vintage / Sourced Guide / Text after When in doubt, ask first','text','[data-content-slot="workshop-journal-handmade-vintage-sourced-guide.text.heading.6.body"]','textContent','If a listing has a special finish, a vintage condition detail, a custom sizing question, or product-specific safety notes, the individual listing and direct message take priority over this general guide.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.hero.image','Marketplace Guide / Hero image','image','[data-media-slot="marketplaces.hero.image"]','src','/assets/placeholders/media-content/marketplaces-hero-image.svg','Marketplace Guide visual',1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.section.visual.1','Marketplace Guide / How to read our listings visual','image','[data-media-slot="marketplaces.section.visual.1"]','src','/assets/placeholders/media-content/marketplaces-section-visual-1.svg','Placeholder for How to read our listings',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.background.hero','Marketplace Guide / Hero background','background','[data-media-background-slot="marketplaces.background.hero"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.background.section-1','Marketplace Guide / How to read our listings background','background','[data-media-background-slot="marketplaces.background.section-1"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.h1','Marketplace Guide / Main heading: Understand Devil n Dove sale channels and marketplace links','text','[data-content-slot="marketplaces.text.h1"]','textContent','Understand Devil n Dove sale channels and marketplace links',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.h1.body','Marketplace Guide / Text after Understand Devil n Dove sale channels and marketplace l','text','[data-content-slot="marketplaces.text.h1.body"]','textContent','Some Devil n Dove items are sold directly here, some are hybrid-listed, and some are easier to sell on Facebook Marketplace or another venue. This page explains how we keep those differences visible.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.2','Marketplace Guide / Heading: How to read our listings','text','[data-content-slot="marketplaces.text.heading.2"]','textContent','How to read our listings',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.3','Marketplace Guide / Heading: Marketplace channels','text','[data-content-slot="marketplaces.text.heading.3"]','textContent','Marketplace channels',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.3.body','Marketplace Guide / Text after Marketplace channels','text','[data-content-slot="marketplaces.text.heading.3.body"]','textContent','Facebook Marketplace, local vending, and other outside channels can be useful for larger items, pickup-friendly pieces, old tools, curiosities, and one-off finds that are easier to explain in a direct listing or local conversation.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.4','Marketplace Guide / Heading: Pickup, support, and local questions','text','[data-content-slot="marketplaces.text.heading.4"]','textContent','Pickup, support, and local questions',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.4.body','Marketplace Guide / Text after Pickup, support, and local questions','text','[data-content-slot="marketplaces.text.heading.4.body"]','textContent','We are based in Southern Ontario, Canada. That means some buyers are local enough to ask about pickup, viewing, or timing before they commit to a purchase. We would rather have those questions asked early than leave uncertainty about channel, travel, or packaging.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.5','Marketplace Guide / Heading: Handmade work','text','[data-content-slot="marketplaces.text.heading.5"]','textContent','Handmade work',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.5.body','Marketplace Guide / Text after Handmade work','text','[data-content-slot="marketplaces.text.heading.5.body"]','textContent','Handmade items should point shoppers back to process, materials, and the wider workshop story.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.6','Marketplace Guide / Heading: Vintage & collectible stock','text','[data-content-slot="marketplaces.text.heading.6"]','textContent','Vintage & collectible stock',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.6.body','Marketplace Guide / Text after Vintage & collectible stock','text','[data-content-slot="marketplaces.text.heading.6.body"]','textContent','Found items should show provenance clues, era notes, and condition summaries before a buyer follows any outside link.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.7','Marketplace Guide / Heading: About the sourcing side','text','[data-content-slot="marketplaces.text.heading.7"]','textContent','About the sourcing side',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/marketplaces','marketplaces.text.heading.7.body','Marketplace Guide / Text after About the sourcing side','text','[data-content-slot="marketplaces.text.heading.7.body"]','textContent','Our About and Creations pages explain why the site now includes handmade work alongside vintage, antique, collectible, and oddity inventory.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.hero.image','Local Pickup / Hero image','image','[data-media-slot="pickup.hero.image"]','src','/assets/images/site/pickup-package-mockup.webp','Representative Devil n Dove order prepared for local pickup',1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.image.2','Local Pickup / Representative Devil n Dove order prepared for local pickup','image','[data-media-slot="pickup.image.2"]','src','/assets/images/site/pickup-package-mockup.webp','Representative Devil n Dove order prepared for local pickup',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.background.hero','Local Pickup / Hero background','background','[data-media-background-slot="pickup.background.hero"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.background.section-1','Local Pickup / Pickup-ready order photo background','background','[data-media-background-slot="pickup.background.section-1"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.background.section-2','Local Pickup / Section background','background','[data-media-background-slot="pickup.background.section-2"]','background-image',NULL,NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.text.h1','Local Pickup / Main heading: Understand local pickup, availability, and support before checkout','text','[data-content-slot="pickup.text.h1"]','textContent','Understand local pickup, availability, and support before checkout',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.text.h1.body','Local Pickup / Text after Understand local pickup, availability, and support befo','text','[data-content-slot="pickup.text.h1.body"]','textContent','Some items are easier to ship, some are better handled through local pickup, and some external or hybrid listings need one more conversation before a buyer commits.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.text.heading.2','Local Pickup / Heading: Pickup-ready order photo','text','[data-content-slot="pickup.text.heading.2"]','textContent','Pickup-ready order photo',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.text.heading.2.body','Local Pickup / Text after Pickup-ready order photo','text','[data-content-slot="pickup.text.heading.2.body"]','textContent','A real pickup-ready product or packaging image can clarify what customers receive.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.text.heading.3','Local Pickup / Heading: When pickup makes sense','text','[data-content-slot="pickup.text.heading.3"]','textContent','When pickup makes sense',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.text.heading.4','Local Pickup / Heading: What to confirm','text','[data-content-slot="pickup.text.heading.4"]','textContent','What to confirm',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.text.heading.5','Local Pickup / Heading: Best next click','text','[data-content-slot="pickup.text.heading.5"]','textContent','Best next click',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/pickup','pickup.text.heading.5.body','Local Pickup / Text after Best next click','text','[data-content-slot="pickup.text.heading.5.body"]','textContent','Use the Contact page to ask about timing, pickup, or external listing availability. Use the Collections and Marketplaces pages when you need more context first.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/movies','movies.hero.image','Movie Shelf / Hero image','image','[data-media-slot="movies.hero.image"]','src','/assets/banner-spicing-it-up.webp','Devil n Dove banner artwork',1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/movies','movies.image.1','Movie Shelf / Devil n Dove banner artwork','image','[data-media-slot="movies.image.1"]','src','/assets/banner-spicing-it-up.webp','Devil n Dove banner artwork',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/movies','movies.text.h1','Movie Shelf / Main heading: DVD and Blu-ray movie collection','text','[data-content-slot="movies.text.h1"]','textContent','DVD and Blu-ray movie collection',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/movies','movies.text.h1.body','Movie Shelf / Text after DVD and Blu-ray movie collection','text','[data-content-slot="movies.text.h1.body"]','textContent','Browse the collection with cover art, searchable metadata, and trailer-ready links while the library keeps being enriched.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.h1','Privacy Policy / Main heading: Privacy Policy','text','[data-content-slot="privacy.text.h1"]','textContent','Privacy Policy',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.h1.body','Privacy Policy / Text after Privacy Policy','text','[data-content-slot="privacy.text.h1.body"]','textContent','How Devil n Dove collects, uses, protects, and handles website, order, media, and social-platform information.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.2','Privacy Policy / Heading: Information we collect','text','[data-content-slot="privacy.text.heading.2"]','textContent','Information we collect',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.2.body','Privacy Policy / Text after Information we collect','text','[data-content-slot="privacy.text.heading.2.body"]','textContent','We collect information people choose to provide when they create an account, place an order, request a custom item, contact us, join a waitlist, submit media, or connect a social account. This can include names, contact details, shipping or pickup details, order information, account identifiers, and messages.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.3','Privacy Policy / Heading: Website and device information','text','[data-content-slot="privacy.text.heading.3"]','textContent','Website and device information',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.3.body','Privacy Policy / Text after Website and device information','text','[data-content-slot="privacy.text.heading.3.body"]','textContent','Our hosting, security, analytics, and commerce services may process IP address, browser type, device information, pages visited, referral information, timestamps, cookies, and security events. We use this information to operate the site, prevent abuse, understand performance, and improve products and content.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.4','Privacy Policy / Heading: Social-platform connections','text','[data-content-slot="privacy.text.heading.4"]','textContent','Social-platform connections',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.4.body','Privacy Policy / Text after Social-platform connections','text','[data-content-slot="privacy.text.heading.4.body"]','textContent','When an administrator connects Facebook, Instagram, Pinterest, X, TikTok, or YouTube, the platform may provide account identifiers, granted permissions, access and refresh tokens, token-expiry information, Page or channel identifiers, and publishing results. We use those details only to provide the requested connection, draft, publishing, and reporting features.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.5','Privacy Policy / Heading: How we use information','text','[data-content-slot="privacy.text.heading.5"]','textContent','How we use information',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.6','Privacy Policy / Heading: Sharing and service providers','text','[data-content-slot="privacy.text.heading.6"]','textContent','Sharing and service providers',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.6.body','Privacy Policy / Text after Sharing and service providers','text','[data-content-slot="privacy.text.heading.6.body"]','textContent','Information may be processed by services that help us host the website, store data and media, process payments, deliver messages, analyze performance, or connect social platforms. We disclose only what is reasonably needed for the service. We may also disclose information when legally required or to protect people, property, and the integrity of the service.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.7','Privacy Policy / Heading: Retention and security','text','[data-content-slot="privacy.text.heading.7"]','textContent','Retention and security',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.7.body','Privacy Policy / Text after Retention and security','text','[data-content-slot="privacy.text.heading.7.body"]','textContent','We retain information only as long as reasonably needed for the purpose collected, legal obligations, dispute handling, security, and business records. Social tokens should be encrypted and revoked when disconnected. No system can promise absolute security, but we use access controls, encrypted secrets, audit logs, and least-privilege design.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.8','Privacy Policy / Heading: Your choices','text','[data-content-slot="privacy.text.heading.8"]','textContent','Your choices',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/privacy','privacy.text.heading.8.body','Privacy Policy / Text after Your choices','text','[data-content-slot="privacy.text.heading.8.body"]','textContent','You may ask to access, correct, or delete eligible personal information, withdraw consent where applicable, or disconnect a social-platform connection. Some transaction and security records may need to be retained. See our Data Deletion Instructions .',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.h1','Terms of Use & Sale / Main heading: Terms of Use and Sale','text','[data-content-slot="terms.text.h1"]','textContent','Terms of Use and Sale',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.h1.body','Terms of Use & Sale / Text after Terms of Use and Sale','text','[data-content-slot="terms.text.h1.body"]','textContent','Terms for using Devil n Dove, ordering handmade or vintage products, custom requests, media, and social publishing.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.2','Terms of Use & Sale / Heading: Using the site','text','[data-content-slot="terms.text.heading.2"]','textContent','Using the site',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.2.body','Terms of Use & Sale / Text after Using the site','text','[data-content-slot="terms.text.heading.2.body"]','textContent','You may browse the site and use its features for lawful personal or business interactions with Devil n Dove. Do not attempt to interfere with the service, bypass access controls, upload harmful material, impersonate another person, or use the site for fraud or spam.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
INSERT INTO media_content_slots(page_path,slot_key,slot_label,slot_type,target_selector,target_attribute,source_snapshot,source_alt_snapshot,is_required,is_active,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES
  ('/terms','terms.text.heading.3','Terms of Use & Sale / Heading: Products and workshop work','text','[data-content-slot="terms.text.heading.3"]','textContent','Products and workshop work',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.3.body','Terms of Use & Sale / Text after Products and workshop work','text','[data-content-slot="terms.text.heading.3.body"]','textContent','Many items are handmade, experimental, vintage, collectible, one-of-a-kind, or produced in small batches. Natural variation, tool marks, patina, and differences from photographs may occur. Product pages should identify known materials, condition, origin, dimensions, limitations, and availability as accurately as reasonably possible.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.4','Terms of Use & Sale / Heading: Orders, pricing, and tax','text','[data-content-slot="terms.text.heading.4"]','textContent','Orders, pricing, and tax',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.4.body','Terms of Use & Sale / Text after Orders, pricing, and tax','text','[data-content-slot="terms.text.heading.4.body"]','textContent','Prices are shown in the currency identified at checkout and may change before an order is accepted. Applicable taxes, shipping, delivery, or pickup terms are shown during checkout or quotation. An automated acknowledgement is not necessarily final acceptance if inventory, pricing, payment, or listing information is incorrect.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.5','Terms of Use & Sale / Heading: Custom requests','text','[data-content-slot="terms.text.heading.5"]','textContent','Custom requests',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.5.body','Terms of Use & Sale / Text after Custom requests','text','[data-content-slot="terms.text.heading.5.body"]','textContent','Custom work may require a written scope, approved design, deposit, material confirmation, production estimate, and consent for any submitted media. Timelines are estimates and can change because of health, materials, equipment, weather, or other workshop conditions.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.6','Terms of Use & Sale / Heading: Content and intellectual property','text','[data-content-slot="terms.text.heading.6"]','textContent','Content and intellectual property',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.6.body','Terms of Use & Sale / Text after Content and intellectual property','text','[data-content-slot="terms.text.heading.6.body"]','textContent','Devil n Dove site text, original photographs, graphics, videos, designs, and branding remain protected by applicable rights unless stated otherwise. Customer-supplied material must be owned or properly licensed by the customer. Connecting a social account does not transfer ownership of platform content.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.7','Terms of Use & Sale / Heading: Social publishing','text','[data-content-slot="terms.text.heading.7"]','textContent','Social publishing',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.7.body','Terms of Use & Sale / Text after Social publishing','text','[data-content-slot="terms.text.heading.7.body"]','textContent','Social integrations are intended for Devil n Dove-owned accounts. Draft automation does not guarantee publication. Administrators remain responsible for reviewing facts, media rights, privacy, platform rules, captions, links, and disclosures before any post is approved.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.8','Terms of Use & Sale / Heading: Availability and limitations','text','[data-content-slot="terms.text.heading.8"]','textContent','Availability and limitations',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/terms','terms.text.heading.8.body','Terms of Use & Sale / Text after Availability and limitations','text','[data-content-slot="terms.text.heading.8.body"]','textContent','The website and integrations are provided on an as-available basis. Third-party platforms can change permissions, pricing, limits, or APIs without notice. To the extent permitted by law, Devil n Dove is not responsible for indirect losses caused by outages, platform changes, unauthorized activity outside our reasonable control, or reliance on workshop/editorial information.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/data-deletion','data-deletion.text.h1','Data Deletion / Main heading: Data Deletion Instructions','text','[data-content-slot="data-deletion.text.h1"]','textContent','Data Deletion Instructions',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/data-deletion','data-deletion.text.h1.body','Data Deletion / Text after Data Deletion Instructions','text','[data-content-slot="data-deletion.text.h1.body"]','textContent','How to request deletion of eligible Devil n Dove account, media, and connected social-platform information.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/data-deletion','data-deletion.text.heading.2','Data Deletion / Heading: Request deletion from Devil n Dove','text','[data-content-slot="data-deletion.text.heading.2"]','textContent','Request deletion from Devil n Dove',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/data-deletion','data-deletion.text.heading.2.body','Data Deletion / Text after Request deletion from Devil n Dove','text','[data-content-slot="data-deletion.text.heading.2.body"]','textContent','We may ask for reasonable verification before deleting or releasing account information.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/data-deletion','data-deletion.text.heading.3','Data Deletion / Heading: Disconnect a social platform','text','[data-content-slot="data-deletion.text.heading.3"]','textContent','Disconnect a social platform',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/data-deletion','data-deletion.text.heading.3.body','Data Deletion / Text after Disconnect a social platform','text','[data-content-slot="data-deletion.text.heading.3.body"]','textContent','Use the platform''s own Apps and Websites or connected-app settings to revoke Devil n Dove access. Revocation stops future API access but may not delete posts already published. You may also ask us to remove stored connection tokens and identifiers.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/data-deletion','data-deletion.text.heading.4','Data Deletion / Heading: What may be retained','text','[data-content-slot="data-deletion.text.heading.4"]','textContent','What may be retained',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/data-deletion','data-deletion.text.heading.4.body','Data Deletion / Text after What may be retained','text','[data-content-slot="data-deletion.text.heading.4.body"]','textContent','We may retain limited transaction, tax, fraud-prevention, security, audit, consent, dispute, or legal records when required or reasonably necessary. Where full deletion is not permitted, access can be restricted and the information minimized.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/data-deletion','data-deletion.text.heading.5','Data Deletion / Heading: Expected handling','text','[data-content-slot="data-deletion.text.heading.5"]','textContent','Expected handling',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/data-deletion','data-deletion.text.heading.5.body','Data Deletion / Text after Expected handling','text','[data-content-slot="data-deletion.text.heading.5.body"]','textContent','We will acknowledge a complete request and provide a status or ask for needed verification. Timing depends on the request, account verification, backups, legal obligations, and connected services.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.h1','Social Connection Disclosure / Main heading: Social Platform Connection Disclosure','text','[data-content-slot="social-connections.text.h1"]','textContent','Social Platform Connection Disclosure',NULL,1,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.h1.body','Social Connection Disclosure / Text after Social Platform Connection Disclosure','text','[data-content-slot="social-connections.text.h1.body"]','textContent','How Devil n Dove uses authorized Facebook, Instagram, Pinterest, X, TikTok, and YouTube connections.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.heading.2','Social Connection Disclosure / Heading: What connecting means','text','[data-content-slot="social-connections.text.heading.2"]','textContent','What connecting means',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.heading.2.body','Social Connection Disclosure / Text after What connecting means','text','[data-content-slot="social-connections.text.heading.2.body"]','textContent','A connected platform authorizes Devil n Dove to perform only the scopes approved on the platform''s consent screen. We do not receive the social account password. Connections are used for Devil n Dove-owned Pages, professional accounts, boards, profiles, or channels.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.heading.3','Social Connection Disclosure / Heading: Review-first publishing','text','[data-content-slot="social-connections.text.heading.3"]','textContent','Review-first publishing',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.heading.3.body','Social Connection Disclosure / Text after Review-first publishing','text','[data-content-slot="social-connections.text.heading.3.body"]','textContent','Eligible products may create internal draft packages, but drafts remain unpublished until reviewed. Media rights, privacy, product facts, destination, caption, links, and platform status must be checked before publishing.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.heading.4','Social Connection Disclosure / Heading: Data handled','text','[data-content-slot="social-connections.text.heading.4"]','textContent','Data handled',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.heading.4.body','Social Connection Disclosure / Text after Data handled','text','[data-content-slot="social-connections.text.heading.4.body"]','textContent','The integration may store provider name, account and Page/channel identifiers, granted scopes, encrypted tokens, expiry times, connection status, post identifiers, timestamps, errors, and aggregate performance results. Tokens must remain server-side.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.heading.5','Social Connection Disclosure / Heading: Disconnecting','text','[data-content-slot="social-connections.text.heading.5"]','textContent','Disconnecting',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.heading.5.body','Social Connection Disclosure / Text after Disconnecting','text','[data-content-slot="social-connections.text.heading.5.body"]','textContent','Connections can be revoked through the social platform and, when the in-app controls are completed, through Devil n Dove. See Data Deletion Instructions for removal requests.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.heading.6','Social Connection Disclosure / Heading: Registered callback URLs','text','[data-content-slot="social-connections.text.heading.6"]','textContent','Registered callback URLs',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/social-connections','social-connections.text.heading.6.body','Social Connection Disclosure / Text after Registered callback URLs','text','[data-content-slot="social-connections.text.heading.6.body"]','textContent','These endpoints are present so provider dashboards can validate exact HTTPS redirect locations. They do not publish content by themselves.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
